from pathlib import Path
import re
root=Path('app/src/main/java/com/halo/app')
def edit(path, fn):
 p=root/path; s=p.read_text(encoding='utf-8'); p.write_text(fn(s),encoding='utf-8')
edit('ui/screens/settings/NotificationSettingsScreen.kt',lambda s:s.replace('    val postPermission = androidx.activity.compose.rememberLauncherForActivityResult(androidx.activity.result.contract.ActivityResultContracts.RequestPermission()) { }','').replace('    DisposableEffect(lifecycle) {','    val postPermission = androidx.activity.compose.rememberLauncherForActivityResult(androidx.activity.result.contract.ActivityResultContracts.RequestPermission()) { refresh() }\n    DisposableEffect(lifecycle) {').replace('            AttentionSettingsSection()\n            Text(uiText("Notifications & Digests"), style = MaterialTheme.typography.headlineSmall)','            Text(uiText("Notifications & Digests"), style = MaterialTheme.typography.headlineSmall)\n            Text(uiText("Reading notifications and showing Halo notifications are separate permissions. You can decline either."))\n            AttentionSettingsSection()').replace('Text(policy.name)','Text(uiText(notificationPolicyLabel(policy)))').replace('Text(option.name)','Text(uiText(notificationPolicyLabel(option)))').replace('} catch (e: Exception) { policyError = e.message }','} catch (cancelled: kotlinx.coroutines.CancellationException) { throw cancelled }\n                                catch (_: Exception) { policyError = "Could not save notification access. Try again." }').replace('Text(it, color = MaterialTheme.colorScheme.error)','Text(uiText("Could not update notification settings. Try again."), color = MaterialTheme.colorScheme.error)')+'\ninternal fun notificationPolicyLabel(policy: NotificationAccessPolicy): String = when(policy) {\n    NotificationAccessPolicy.ALLOW -> "Read and use notifications"\n    NotificationAccessPolicy.SUMMARIZE_ONLY -> "Summaries only"\n    NotificationAccessPolicy.HIDE_CONTENT -> "Hide notification content"\n    NotificationAccessPolicy.BLOCK -> "Blocked"\n}\n')
edit('ui/screens/settings/LearningSettingsScreen.kt',lambda s:s.replace('Text("Lexical search available · Semantic model not installed", style = MaterialTheme.typography.bodySmall)','Text(uiText("Memory retrieval depends on available search capabilities and your privacy settings."), style = MaterialTheme.typography.bodySmall)').replace('Text(label,','Text(uiText(label),').replace('Text(when (mode) {','Text(uiText(when (mode) {').replace('"Suggest" })','"Suggest" }))').replace('            })','            }))').replace('Text(if (memoryUse) "Halo may retrieve relevant saved memories within the current scope and context budget." else "Saved memories stay in Memory. Automatic conversational use is off.")','Text(uiText(if (memoryUse) "Halo may retrieve relevant saved memories within the current scope and context budget." else "Saved memories stay in Memory. Automatic conversational use is off."))'))
# Wire literal authored labels, preserving all interpolated source/user content.
for name in ['LearningSettingsScreen','AndroidAssistantScreen','AutomationSandboxScreen']:
 p=root/f'ui/screens/settings/{name}.kt'; s=p.read_text(encoding='utf-8')
 if 'import com.halo.app.language.uiText' not in s:s=s.replace('\n\n','\n\nimport com.halo.app.language.uiText\n',1)
 s=re.sub(r'(?<![A-Za-z0-9_])Text\(("[^"$\\\n]+")',r'Text(uiText(\1)',s)
 p.write_text(s,encoding='utf-8')
